#include <climits>
#include <iostream>
#include <vector>
using namespace std;

//Driver Code Ends

vector<vector<int>> nearest(vector<vector<int>> &grid)
{
    int n = grid.size();
    int m = grid[0].size();

    vector<vector<int>> ans(n, vector<int>(m, INT_MAX));

    // visit each cell of the grid
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {

            // if the cell has 1,
            // then the distance is 0
            if (grid[i][j] == 1)
            {
                ans[i][j] = 0;
                continue;
            }

            // iterate over all the cells
            // and find the distance of the nearest 1
            for (int k = 0; k < n; k++)
            {
                for (int l = 0; l < m; l++)
                {
                    if (grid[k][l] == 1)
                    {
                        ans[i][j] = min(ans[i][j], abs(i - k) + abs(j - l));
                    }
                }
            }
        }
    }

    return ans;
}

//Driver Code Starts

int main()
{
    vector<vector<int>> grid = {{0, 1, 1, 0}, {1, 1, 0, 0}, {0, 0, 1, 1}};
    vector<vector<int>> ans = nearest(grid);
    for (int i = 0; i < ans.size(); i++)
    {
        for (int j = 0; j < ans[i].size(); j++)
        {
            cout << ans[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}
