    static ArrayList<ArrayList<Integer>>nearest(int[][] grid)
    {
        int n = grid.length;
        int m = grid[0].length;

        ArrayList<ArrayList<Integer> > ans
            = new ArrayList<>();

        // initialize all cells with maximum value
        for (int i = 0; i < n; i++) {
            ArrayList<Integer> row = new ArrayList<>();
            for (int j = 0; j < m; j++) {
                row.add(Integer.MAX_VALUE);
            }
            ans.add(row);
        }

        // visit each cell of the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {

                // if the cell has 1, distance is 0
                if (grid[i][j] == 1) {
                    ans.get(i).set(j, 0);
                    continue;
                }

                // iterate over all cells to find nearest 1
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < m; l++) {
                        if (grid[k][l] == 1) {
                            int distance
                                = Math.abs(i - k)
                                  + Math.abs(j - l);
                            if (distance
                                < ans.get(i).get(j)) {
                                ans.get(i).set(j, distance);
                            }
                        }
                    }
                }
            }
        }
        return ans;
    }

