        // and find the distance of the nearest 1
        while (q.Count > 0)
        {
            int len = q.Count;

            for (int i = 0; i < len; i++)
            {
                var node = q.Dequeue();
                int x = node.Item1;
                int y = node.Item2;

                // check all the four directions
